package za.co.innaesim.backup.model;

import lombok.Data;
import lombok.ToString;

/**
 * A remote location. Which fields apply depends on {@code type}: ftp, sftp, s3 or azure.
 *
 * Getters and setters are generated by Lombok, so they don't appear in this documentation.
 */
@Data
public class DestinationConfig {
    private String name;
    private String type;

    // ftp, sftp
    private String host;
    private Integer port;
    private String user;
    @ToString.Exclude
    private String password;
    private String path;
    private boolean tls;
    private String keyFile;
    @ToString.Exclude
    private String keyPassphrase;
    private String knownHosts;

    // s3, azure
    private String prefix;
    private String bucket;
    private String region;
    private String endpoint;
    private String accessKey;
    @ToString.Exclude
    private String secretKey;
    private String container;
    @ToString.Exclude
    private String connectionString;

    /** Creates an empty destination. */
    public DestinationConfig() {}
}
